console.log("Скрипт корректировки загружен!");
const TPL = ""; 

const W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
const W14 = "http://schemas.microsoft.com/office/word/2010/wordml";
const MEALS = [
 {k:"b",name:"ЗАВТРАК",label:"Завтрак",re:/ЗАВТРАК|BREAKFAST|ТАМАҒЫ/i,kk:"ТАҢҒЫ АС МӘЗІРІ",ru:"МЕНЮ ЗАВТРАК",en:"BREAKFAST MENU"},
 {k:"l",name:"ОБЕД",label:"Обед",re:/ОБЕД|LUNCH|ТҮСКІ/i,kk:"ТҮСКІ АС МӘЗІРІ",ru:"МЕНЮ ОБЕД",en:"LUNCH MENU"},
 {k:"d",name:"УЖИН",label:"Ужин",re:/УЖИН|DINNER|КЕШКІ/i,kk:"КЕШКІ АС МӘЗІРІ",ru:"МЕНЮ УЖИН",en:"DINNER MENU"}
];
const WD = ["Пн","Вт","Ср","Чт","Пт","Сб","Вс"];
const EP = Date.UTC(1899,11,30);

// Инициализация глобальных переменных
window.weeks = [];
window.cur = { week: 0 };
window.TM = {
  data: JSON.parse(localStorage.getItem('translation_memory') || '{}'),
  get: function(ruText) { return this.data[ruText] || {}; },
  set: function(ruText, lang, text) {
    if (!ruText || !text) return;
    if (!this.data[ruText]) this.data[ruText] = {};
    this.data[ruText][lang] = text;
    localStorage.setItem('translation_memory', JSON.stringify(this.data));
  }
};
// Временные правки, привязанные к дате
window.tempOverrides = {};
window.tempHidden = {};

const clean = v => String(v==null?"":v).replace(/\s+/g," ").trim();

function toSerial(v){
  if(typeof v==="number"&&v>40000&&v<60000)return v;
  if(typeof v==="string"){const m=v.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);if(m)return(Date.UTC(+m[3],m[2]-1,+m[1])-EP)/864e5}
  return null;
}
function fmt(s,sep){const d=new Date(EP+Math.round(s)*864e5);const p=n=>String(n).padStart(2,"0");return p(d.getUTCDate())+sep+p(d.getUTCMonth()+1)+sep+d.getUTCFullYear()}
const wday = s => WD[(new Date(EP+Math.round(s)*864e5).getUTCDay()+6)%7];

function detectLang(rows){
  let kz=0,cy=0,la=0;
  for(const row of rows)for(let c=2;c<=8;c++){
    const v=clean(row[c]);if(!v||toSerial(row[c])!=null&&typeof row[c]==="number")continue;
    if(/[әіңғүұқөһӘІҢҒҮҰҚӨҺ]/.test(v))kz++;else if(/[А-Яа-яЁё]/.test(v))cy++;else if(/[A-Za-z]/.test(v))la++;
  }
  return la>cy+kz?"en":(kz>=5&&kz>cy*0.5?"kk":"ru");
}

function parseWb(wb){
  const g={};
  for(const n of wb.SheetNames){
    const m=n.match(/\d+/);if(!m)continue;
    const rows=XLSX.utils.sheet_to_json(wb.Sheets[n],{header:1,raw:true,defval:""});
    const lang=detectLang(rows),w=(g[m[0]]=g[m[0]]||{num:+m[0],names:{}});
    if(!w[lang]){w[lang]=rows;w.names[lang]=n}
  }
  const out=[];
  for(const w of Object.values(g).sort((a,b)=>a.num-b.num)){
    if(!w.ru)continue;
    let dr=-1;
    for(let r=0;r<30&&dr<0;r++){
      const c=[2,3,4,5,6,7,8].filter(i=>toSerial((w.ru[r]||[])[i])!=null);
      if(c.length>=5)dr=r;
    }
    if(dr<0)continue;
    w.dates=[2,3,4,5,6,7,8].map(i=>toSerial(w.ru[dr][i]));
    const st=[];w.labels=[];
    w.ru.forEach((row,r)=>{
      if(r<dr)return;
      const a0=clean(row[0]);if(a0)w.labels.push((r+1)+": "+a0.slice(0,28));
      const a=a0||clean(row[1]);if(!a)return;
      const mk=MEALS.find(m=>m.re.test(a));
      if(mk&&!st.some(x=>x[0]===mk.k))st.push([mk.k,r]);
    });
    const ls=st.find(x=>x[0]==="l");
    if(ls&&!st.some(x=>x[0]==="b")&&ls[1]>dr+1)st.unshift(["b",dr+1]);
    w.blocks={};
    st.forEach(([k,s],i)=>{
      const e=i+1<st.length?st[i+1][1]:w.ru.length,seen={},list=[];
      for(let r=s;r<e;r++){
        const row=w.ru[r]||[],all=row.map(clean).join(" ");
        if(/Manager|Boss|Chief|Cook|Date:|Representative/i.test(all))continue;
        let lb=clean(row[1]);
        if(!lb&&[2,3,4,5,6,7,8].some(i=>clean(row[i])))lb="Строка "+(r+1);
        if(!lb)continue;
        seen[lb]=(seen[lb]||0)+1;
        list.push({label:lb,r,key:lb+(seen[lb]>1?"#"+seen[lb]:"")});
      }
      w.blocks[k]=list;
    });
    out.push(w);
  }
  return out;
}

const get = (w,lang,r,c)=>clean(((w[lang]||w.ru)[r]||[])[c]);

function texts(d,it){
  const ov=(lang)=>{
    const ruText = it.isCustom ? (it.ru||"") : get(d.w, "ru", it.r, d.col);
    const k = lang + "|" + d.serial + "|" + ruText; // Ключ с датой
    
    if(window.tempOverrides[k] !== undefined) return window.tempOverrides[k];
    
    if (lang !== 'ru' && ruText && ruText.trim() !== "") {
        const mem = window.TM.get(ruText.trim());
        if (mem[lang]) return mem[lang];
    }
    if(it.isCustom) return it[lang]||"";
    return get(d.w,lang,it.r,d.col);
  };
  const t={ru:ov("ru"),kk:ov("kk"),en:ov("en")};
  t.warn=!t.ru||!t.kk||!t.en||t.kk===t.ru||/[А-Яа-яЁё]/.test(t.en)||!/[А-Яа-яЁё]/.test(t.ru);
  return t;
}

function say(t,bad){
  const m=document.getElementById("msg");
  m.textContent=t;
  m.style.color=bad?"var(--warn)":"var(--mute)";
}

function setCellText(doc,tc,text){
  const p=tc.getElementsByTagNameNS(W,"p")[0];
  const r0=[...p.getElementsByTagNameNS(W,"r")].find(r=>r.getElementsByTagNameNS(W,"t").length);
  const rPr=r0&&r0.getElementsByTagNameNS(W,"rPr")[0];
  const copy=rPr?rPr.cloneNode(true):null;
  [...p.childNodes].forEach(n=>{if(n.localName!=="pPr")p.removeChild(n)});
  const r=doc.createElementNS(W,"w:r");if(copy)r.appendChild(copy);
  const t=doc.createElementNS(W,"w:t");
  t.setAttributeNS("http://www.w3.org/XML/1998/namespace","xml:space","preserve");
  t.textContent=text;r.appendChild(t);p.appendChild(r);
}
function stripIds(e){
  const all=[e,...e.getElementsByTagNameNS(W,"p")];
  all.forEach(x=>{x.removeAttributeNS(W14,"paraId");x.removeAttributeNS(W14,"textId")});
}

async function buildDocxDay(dayObj,day,mealKey){
  const list=dayObj.w.blocks[mealKey]||[];
  const picked = list.filter(it => !window.tempHidden[dayObj.serial + "|" + it.key]);
  const meal=MEALS.find(m=>m.k===mealKey);

  const zip=await JSZip.loadAsync(TPL,{base64:true});
  const xml=await zip.file("word/document.xml").async("string");
  const doc=new DOMParser().parseFromString(xml,"application/xml");
  const body=doc.getElementsByTagNameNS(W,"body")[0];

  const p0=body.getElementsByTagNameNS(W,"p")[0];
  const runs=[...p0.getElementsByTagNameNS(W,"r")].filter(r=>r.getElementsByTagNameNS(W,"t").length);
  runs[0].getElementsByTagNameNS(W,"t")[0].textContent=fmt(dayObj.serial,".");
  runs.slice(1).forEach(r=>r.parentNode.removeChild(r));

  const tbl=body.getElementsByTagNameNS(W,"tbl")[0];
  const trs=[...tbl.getElementsByTagNameNS(W,"tr")],head=trs[0],proto=trs[1];
  trs.slice(1).forEach(r=>r.parentNode.removeChild(r));
  [meal.kk,meal.ru,meal.en].forEach((t,i)=>setCellText(doc,head.getElementsByTagNameNS(W,"tc")[i],t));

  picked.forEach(it=>{
    const t=texts(dayObj,it),row=proto.cloneNode(true);stripIds(row);
    [t.kk,t.ru,t.en].forEach((x,i)=>setCellText(doc,row.getElementsByTagNameNS(W,"tc")[i],x));
    tbl.appendChild(row);
  });
  if(picked.length>12){const pr=tbl.getElementsByTagNameNS(W,"tblpPr")[0];if(pr)pr.parentNode.removeChild(pr)}

  zip.file("word/document.xml",'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'+new XMLSerializer().serializeToString(doc).replace(/^<\?xml[^>]*\?>\s*/,""));
  const data=await zip.generateAsync({type:"uint8array",compression:"DEFLATE"});
  return {name:fmt(dayObj.serial,"_")+"_"+meal.name+".docx",data};
}

function getCategoryGroup(mealKey, label, rawCat) {
  const l = (label + " " + rawCat).toLowerCase();
  if (mealKey === 'b') {
    if (l.includes("злаки") || l.includes("каша")) return "Ботқа / Каша / Porridge";
    if (l.includes("яйца") || l.includes("жұмыртқа") || l.includes("омлет")) return "Жұмыртқа / Яйца / Eggs";
    if (l.includes("горячее") || l.includes("гарнир") || l.includes("сосиск")) return "Ыстық тағам / Горячее / Hot dishes";
    if (l.includes("йогурт") || l.includes("выпечка") || l.includes("тоқаш")) return "Бәліштер және сүт өнімдері / Выпечка и молочные изделия / Bakery and dairy products";
  } else {
    if (l.includes("салатные овощи")) return null;
    if (l.includes("суп")) return "Сорпа / Суп / Soup";
    if (l.includes("салат")) return "Салат / Salat";
    if (l.includes("блюдо")) return "Тағам / Блюдо / Dish";
    if (l.includes("гарнир")) return "Гарнир / Garnish";
    if (l.includes("овощи")) return "Овощи";
  }
  return null;
}

async function buildJpegByMeal(dayObj, day, mealKey) {
  const w = dayObj.w;
  const meal = MEALS.find(m => m.k === mealKey);
  const list = w.blocks[mealKey] || [];
  const picked = list.filter(it => !window.tempHidden[dayObj.serial + "|" + it.key]);

  const container = document.getElementById('jpegContainer');
  container.style.width = '1400px';
  container.style.padding = '20px 40px';
  container.style.backgroundColor = '#f7eed8'; 
  container.style.fontFamily = "'Times New Roman', serif";
  container.style.color = '#000000';
  container.style.boxSizing = 'border-box';
  
  let html = `
    <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 3px solid #2b5782; padding-bottom: 15px; margin-bottom: 20px;">
      <img src="data:image/png;base64," style="height: 120px !important; max-height: 120px !important; width: auto !important; object-fit: contain; mix-blend-mode: multiply;" alt="KAZ">
      <div style="font-size: 36px; font-weight: bold; color: #2b5782; text-decoration: underline; text-transform: uppercase;">МӘЗІР/МЕНЮ/MENU</div>
      <img src="ВСТАВЬ_СЮДА_ДЛИННУЮ_СТРОКУ_ОТ_LOGO_EURASIA" style="height: 35px !important; max-height: 35px !important; width: auto !important; object-fit: contain; mix-blend-mode: multiply;" alt="Eurasia">
    </div>
    <div style="text-align: center; font-size: 26px; margin-bottom: 20px; font-weight: bold;">
      ${fmt(dayObj.serial, ".")} &nbsp;&nbsp;&nbsp; ${meal.name}
    </div>
  `;

  if (!picked.length) {
    container.innerHTML = html + `<div style="text-align:center; padding:50px; font-size:24px;">Нет блюд</div>`;
    const emptyCanvas = await html2canvas(container, { scale: 2, backgroundColor: "#f7eed8" });
    return new Promise(res => emptyCanvas.toBlob(b => res(b), 'image/jpeg', 0.95));
  }

  const groups = {};
  picked.forEach(it => {
    const groupName = getCategoryGroup(mealKey, it.label, it.cat || "");
    if (groupName) {
      if (!groups[groupName]) groups[groupName] = [];
      groups[groupName].push(it);
    }
  });

  if (Object.keys(groups).length === 0) {
    container.innerHTML = html + `<div style="text-align:center; padding:50px; font-size:24px;">Нет блюд по категориям</div>`;
    const filterCanvas = await html2canvas(container, { scale: 2, backgroundColor: "#f7eed8" });
    return new Promise(res => filterCanvas.toBlob(b => res(b), 'image/jpeg', 0.95));
  }

  html += `<table style="width: 100%; border-collapse: collapse; border: 2px solid #2b5782; background: rgba(255,255,255,0.7);">`;
  html += `
    <tr style="background: #e5d8c1; border-bottom: 2px solid #2b5782;">
      <th style="border: 1px solid #2b5782; padding: 12px; width: 20%;"></th>
      <th style="border: 1px solid #2b5782; padding: 12px; width: 26%; font-size: 18px;">${meal.kk}</th>
      <th style="border: 1px solid #2b5782; padding: 12px; width: 26%; font-size: 18px;">${meal.ru}</th>
      <th style="border: 1px solid #2b5782; padding: 12px; width: 28%; font-size: 18px;">${meal.en}</th>
    </tr>
  `;

  for (const [groupName, items] of Object.entries(groups)) {
    items.forEach((it, index) => {
      const t = texts(dayObj, it);
      html += `<tr>`;
      if (index === 0) {
        html += `<td rowspan="${items.length}" style="border: 1px solid #2b5782; padding: 10px; text-align: center; font-weight: bold; font-size: 18px; vertical-align: middle; background: rgba(229,216,193,0.3);">
          ${groupName}
        </td>`;
      }
      html += `
        <td style="border: 1px solid #2b5782; padding: 12px; text-align: center; font-size: 18px;">${t.kk || "—"}</td>
        <td style="border: 1px solid #2b5782; padding: 12px; text-align: center; font-size: 18px;">${t.ru || "—"}</td>
        <td style="border: 1px solid #2b5782; padding: 12px; text-align: center; font-size: 18px;">${t.en || "—"}</td>
      </tr>`;
    });
  }
  html += `</table>`;
  container.innerHTML = html;

  await new Promise(r => setTimeout(r, 200));

  const finalCanvas = await html2canvas(container, {
    scale: 2,
    backgroundColor: "#f7eed8",
    useCORS: true,
    allowTaint: true
  });
  
  return new Promise(res => finalCanvas.toBlob(b => res(b), 'image/jpeg', 0.95));
}

async function saveFile(filename,data){
  try{
    const url=URL.createObjectURL(new Blob([data]));
    const a=document.createElement("a");a.href=url;a.download=filename;
    document.body.append(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),60000);
    say("Готово: "+filename);
  }catch(e){say("Не удалось сохранить: "+((e&&e.message)||e),true)}
}
function saveBlob(filename,blob){
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a");a.href=url;a.download=filename;
  document.body.append(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),60000);
  say("Готово: "+filename);
}

// ===== ОСНОВНАЯ ЛОГИКА СТРАНИЦЫ =====
document.getElementById('file').onchange=async e=>{
  const f=e.target.files[0];if(!f)return;
  try{
    const wb=XLSX.read(await f.arrayBuffer(),{type:"array"});
    window.weeks=parseWb(wb);
    
    if(!window.weeks.length)throw new Error("не нашёл листы с неделями и датами");

    const sel2=document.getElementById("daySelect");
    sel2.replaceChildren();
    window.weeks.forEach((w, weekIndex) => {
    w.dates.forEach((serial, dayIndex) => {
        if (serial == null) return;
        const o = document.createElement("option");
        o.value = weekIndex + "_" + dayIndex; // Сохраняем и неделю, и день
        o.textContent = "Неделя " + w.num + ": " + wday(serial) + ", " + fmt(serial, ".");
        sel2.appendChild(o);
    });
});

    document.getElementById("step2").classList.remove("hide");
    say(f.name+": загружено. Выберите день для правок.");
    renderCorrection();
  }catch(err){say("Не удалось прочитать файл: "+err.message,true)}
};

document.getElementById('daySelect').onchange = renderCorrection;

function renderCorrection() {
  window.TM.data = JSON.parse(localStorage.getItem('translation_memory') || '{}');
  const listContainer = document.getElementById('correctionList');
  listContainer.innerHTML = '';
  
  const val = document.getElementById('daySelect').value;
  if (!val) return;
  const [weekIndex, day] = val.split('_').map(Number);
  const w = window.weeks[weekIndex];
  if (!w) return;

  const serial = w.dates[day];
  if (serial == null) return;

  const dayObj = {w, col: 2 + day, serial};

  MEALS.forEach(meal => {
    const list = w.blocks[meal.k] || [];
    if (!list.length) return;

    const sec = document.createElement('div');
    sec.style.marginBottom = '20px';
    
    const mh = document.createElement('div');
    mh.className = 'meal-header';
    mh.style.marginBottom = '10px';
    mh.textContent = meal.label;
    sec.appendChild(mh);

    list.forEach(it => {
      const t = texts(dayObj, it);
      
      const row = document.createElement('div');
        row.className = 'item';
        row.style.padding = '0';
        row.style.border = 'none';
        row.style.marginBottom = '10px';
        row.style.display = 'flex';
        row.style.gap = '10px';
        row.style.alignItems = 'flex-start';
        
        // СОЗДАЕМ ГАЛОЧКУ
        const cb = document.createElement('input');
        cb.type = 'checkbox';
        const hideKey = dayObj.serial + "|" + it.key;
        cb.checked = !window.tempHidden[hideKey];
        cb.style.marginTop = '10px';
        cb.style.width = '20px';
        cb.style.height = '20px';
        cb.onchange = () => {
            if (cb.checked) delete window.tempHidden[hideKey];
            else window.tempHidden[hideKey] = true;
        };
        row.appendChild(cb);
        
        const body = document.createElement('div');
        body.className = 'item-body';
        body.style.flex = '1';

      const createInput = (cls, lang, val) => {
        const inp = document.createElement('input');
        inp.type = 'text';
        inp.className = cls;
        inp.value = val || '';
        inp.placeholder = lang.toUpperCase();
        inp.style.border = '1px solid var(--line)';
        inp.style.padding = '8px';
        
        inp.oninput = () => {
          const v = inp.value.trim();
          const origRu = it.isCustom ? (it.ru||"") : get(dayObj.w, "ru", it.r, dayObj.col);
          const key = lang + "|" + dayObj.serial + "|" + origRu;
          const orig = it.isCustom ? (it[lang]||"") : get(dayObj.w, lang, it.r, dayObj.col);
          
          if (v === orig) delete window.tempOverrides[key];
          else window.tempOverrides[key] = v;
        };
        return inp;
      };

      body.appendChild(createInput('ru', 'ru', t.ru));
      body.appendChild(createInput('o', 'kk', t.kk));
      body.appendChild(createInput('o', 'en', t.en));
      
      row.appendChild(body);
      sec.appendChild(row);
    });
    listContainer.appendChild(sec);
  });
}

// Кнопки скачивания
document.getElementById('downloadWord').onclick = async () => {
  try {
    const val = document.getElementById('daySelect').value;
    if (!val) return;
    const [weekIndex, day] = val.split('_').map(Number);
    const w = window.weeks[weekIndex];
    const dayObj = {w, col: 2 + day, serial: w.dates[day]};
    
    say("Собираю Word...");
    const out = new JSZip();
    for (const meal of MEALS) {
      if (!(dayObj.w.blocks[meal.k] || []).length) continue;
      const f = await buildDocxDay(dayObj, day, meal.k);
      out.file(f.name, f.data);
    }
    
    const zipName = "Корректировка_" + fmt(dayObj.serial, "_") + ".zip";
    await saveFile(zipName, await out.generateAsync({type:"uint8array"}));
  } catch(e) { say("Ошибка: " + e.message, true); }
};

document.getElementById('downloadJpeg').onclick = async () => {
  try {
    const val = document.getElementById('daySelect').value;
    if (!val) return;
    const [weekIndex, day] = val.split('_').map(Number);
    const w = window.weeks[weekIndex];
    const dayObj = {w, col: 2 + day, serial: w.dates[day]};
    
    say("Собираю JPEG...");
    const out = new JSZip();
    for (const meal of MEALS) {
      if (!(dayObj.w.blocks[meal.k] || []).length) continue;
      const blob = await buildJpegByMeal(dayObj, day, meal.k);
      out.file(fmt(dayObj.serial, "_") + "_" + meal.name + ".jpg", blob);
    }
    
    const zipName = "Корректировка_" + fmt(dayObj.serial, "_") + "_jpeg.zip";
    saveBlob(zipName, await out.generateAsync({type:"blob"}));
  } catch(e) { say("Ошибка: " + e.message, true); }
};
// ===== СМЕНА ТЕМЫ =====
const themeToggleBtn = document.getElementById('themeToggle');
const currentTheme = localStorage.getItem('theme') || 'light';

if (currentTheme === 'dark') {
  document.documentElement.setAttribute('data-theme', 'dark');
  if (themeToggleBtn) themeToggleBtn.textContent = '☀️ Светлая';
}

if (themeToggleBtn) {
  themeToggleBtn.onclick = () => {
    const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    if (isDark) {
      document.documentElement.removeAttribute('data-theme');
      localStorage.setItem('theme', 'light');
      themeToggleBtn.textContent = '🌙 Тёмная';
    } else {
      document.documentElement.setAttribute('data-theme', 'dark');
      localStorage.setItem('theme', 'dark');
      themeToggleBtn.textContent = '☀️ Светлая';
    }
  };
}
// ===== ЛОГИКА ПЕРЕВОДА ИИ ДЛЯ КОРРЕКТИРОВКИ (С ПЕРЕБОРОМ И ТАЙМАУТОМ) =====
async function aiTranslateBatch(items, target) {
  const apiKey = localStorage.getItem('gemini_api_key');
  if (!apiKey) throw new Error('Сначала нажмите «⚙️ Настроить ИИ» на главной странице!');
  
  const langName = target === 'kk' ? 'казахский' : 'английский';
  let finalResult = {};
  
  // Делим на пачки по 30 блюд, чтобы ИИ не зависал
  const chunkSize = 30;
  
  for (let i = 0; i < items.length; i += chunkSize) {
    const chunk = items.slice(i, i + chunkSize);
    console.log(`[ИИ] Отправляю пачку ${i + 1} - ${i + chunk.length} из ${items.length}...`);
    
    const prompt = `Переведи названия блюд с русского на ${langName}. 
Верни результат СТРОГО в формате JSON-объекта, где ключ - это оригинальный русский текст, а значение - перевод.
Не добавляй лишнего текста, только JSON.
Исходный список: ${JSON.stringify(chunk)}`;

    // Рабочие модели (3.8 убрал, так как она часто виснет)
    const models = [
  'gemini-3.8-flash', 
  'gemini-3.7-flash', 
  'gemini-3.6-flash', 
  'gemini-3.5-flash', 
  'gemini-3.5-flash-lite', 
  'gemini-2.5-flash', 
  'gemini-1.5-flash'
];
    let success = false;

    for (const model of models) {
      try {
        console.log(`[ИИ] Пробую модель: ${model}...`);
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
        
        // Ставим таймаут на 15 секунд
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 15000);
        
        const res = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.1 } }),
          signal: controller.signal
        });
        
        clearTimeout(timeoutId);

        if (res.status === 429) { 
            console.warn(`[ИИ] ${model} выдала 429. Жду 3 сек...`);
            await new Promise(r => setTimeout(r, 3000)); 
            continue; 
        }
        
        if (!res.ok) {
            console.warn(`[ИИ] ${model} вернула HTTP ${res.status}. Переключаюсь...`);
            continue;
        }
        
        const data = await res.json();
        let text = data.candidates[0].content.parts[0].text.trim();
        text = text.replace(/```json/gi, '').replace(/```/g, '').trim();
        const m = text.match(/\{[\s\S]*\}/); 
        if (!m) throw new Error('ИИ вернул не JSON');
        
        const parsed = JSON.parse(m[0]);
        Object.assign(finalResult, parsed); // Добавляем переводы к общему результату
        console.log(`[ИИ] УСПЕХ! Модель ${model} перевела пачку.`);
        success = true;
        break; // Выходим из перебора моделей для этой пачки

      } catch (err) {
        if (err.name === 'AbortError') {
            console.warn(`[ИИ] Модель ${model} зависла (таймаут 15 сек). Переключаюсь...`);
        } else {
            console.warn(`[ИИ] Ошибка на модели ${model}: ${err.message}`);
        }
      }
    }
    
    if (!success) throw new Error('Все модели зависли или недоступны. Попробуйте позже.');
    
    // Небольшая пауза между пачками, чтобы не словлить лимиты
    if (i + chunkSize < items.length) await new Promise(r => setTimeout(r, 2000));
  }
  
  return finalResult;
}

document.getElementById('translateAiBtn').onclick = async function() {
  const val = document.getElementById('daySelect').value;
  if (!val) return;
  
  const [weekIndex, day] = val.split('_').map(Number);
  const w = window.weeks[weekIndex];
  const dayObj = {w, col: 2 + day, serial: w.dates[day]};

  // Собираем все уникальные русские слова из этого дня
  const ruTexts = [];
  MEALS.forEach(meal => {
    const list = w.blocks[meal.k] || [];
    list.forEach(it => {
      const ru = it.isCustom ? (it.ru||"") : get(dayObj.w, "ru", it.r, dayObj.col);
      if (ru && ru.trim() !== "" && !ruTexts.includes(ru.trim())) ruTexts.push(ru.trim());
    });
  });

  if (!ruTexts.length) { say("Нет блюд для перевода.", true); return; }

  this.disabled = true;
  try {
    say("ИИ переводит на казахский... (смотрите прогресс в консоли F12)");
    const kkObj = await aiTranslateBatch(ruTexts, 'kk');
    for (const [ru, kk] of Object.entries(kkObj)) window.TM.set(ru, 'kk', kk);
    
    await new Promise(r => setTimeout(r, 1500));
    
    say("ИИ переводит на английский...");
    const enObj = await aiTranslateBatch(ruTexts, 'en');
    for (const [ru, en] of Object.entries(enObj)) window.TM.set(ru, 'en', en);

    say("Готово!");
    renderCorrection(); // Обновляем поля на странице
  } catch (e) {
    say("Ошибка ИИ: " + e.message, true);
  }
  this.disabled = false;
};
